<script setup lang="ts">
import {toRef} from 'vue'
import {WorkforceApiError} from '../api'
import type {BatchSummary} from '../payrollTypes'
import {bulkPayrollEligible,usePayrollBulkProgress} from '../payrollBulkProgress'
import {usePayrollProgressText} from '../payrollProgressText'
const props=defineProps<{items:BatchSummary[];loading?:boolean}>(),emit=defineEmits<{completed:[]}>(),g=usePayrollProgressText()
const {base,message,selected,note,acknowledged,result,command,blocked,valid,busy,failure,toggle,start,recover}=usePayrollBulkProgress(toRef(props,'items'),()=>emit('completed'))
</script>
<template><section class="wf-section wf-payroll-bulk"><h3>{{g('bulk')}}</h3><p class="wf-hint">{{g('bulkHint')}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{g('select')}}</th><th>{{g('month')}}</th><th>{{g('status')}}</th></tr></thead><tbody><tr v-for="batch in items" :key="batch.id"><td><input type="checkbox" :aria-label="g('select')+' '+batch.month" :checked="selected.includes(batch.id)" :disabled="blocked||loading||!bulkPayrollEligible(batch)||(!selected.includes(batch.id)&&selected.length>=20)" @change="toggle(batch,($event.target as HTMLInputElement).checked)"></td><td>{{batch.month}}</td><td>{{g(batch.status)}}</td></tr></tbody></table></div><p>{{g('selected')}} {{selected.length}} / 20</p><label>{{g('note')}}<textarea v-model="note" rows="2" maxlength="500" :disabled="blocked||loading"></textarea></label><p class="wf-hint">{{g('confirmHint')}}</p><label class="wf-bulk-ack"><input v-model="acknowledged" type="checkbox" :disabled="blocked||loading"><span>{{g('ack')}}</span></label><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><div class="wf-inline"><button :disabled="blocked||loading||!valid" @click="start('calculate')">{{g('calculate')}}</button><button :disabled="blocked||loading||!valid" @click="start('calculate_full')">{{g('calculate_full')}}</button><button :disabled="blocked||loading||!valid||!acknowledged" @click="start('confirm')">{{g('confirm')}}</button></div><div v-if="command" role="status"><p class="wf-issue">{{g('uncertain')}}</p><button :disabled="busy" @click="recover">{{g('recover')}}</button></div><section v-if="result" class="wf-section" aria-live="polite"><h4>{{g('results')}}</h4><ul><li v-for="entry in result.results" :key="entry.batchId"><RouterLink :to="base+'/payroll-batches/'+entry.batchId">{{(entry.batch||items.find(b=>b.id===entry.batchId))?.month||g('batch')}}</RouterLink> · {{g(entry.status)}} <template v-if="entry.batch">{{g(entry.batch.status)}}</template><span v-if="entry.code"> · {{message(new WorkforceApiError(409,entry.code))}}</span></li></ul></section></section></template>

<style scoped>.wf-payroll-bulk .wf-bulk-ack{display:flex;flex-direction:row;align-items:flex-start;gap:8px;white-space:normal}.wf-payroll-bulk input[type="checkbox"]{width:20px;min-width:20px;max-width:20px;height:20px;min-height:20px;flex:0 0 20px;padding:0;margin:2px 0}.wf-bulk-ack span{flex:1;min-width:0}.wf-payroll-bulk li{overflow-wrap:anywhere;margin:6px 0}</style>


